from pathlib import Path
import re,json,html
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent
f={k:(R/f'chapters/E07/E07_{k}.html').read_text() for k in ['a','b','c','d','pop1','pop2']};log=[]
def rep(old,new):
 n=0
 for k in f:
  m=f[k].count(old);n+=m;f[k]=f[k].replace(old,new)
 if n:log.append(dict(kind='literal',count=n,old=old,new=new))
 else: print('ABSENT',old[:70])
def para(k,needle,new):
 matches=[m for m in re.finditer(r'<p(?:\s[^>]*)?>[^\n]*?</p>',f[k]) if needle in m.group()];assert matches,(k,needle)
 for m in reversed(matches):log.append(dict(kind='paragraph',file=k,old=m.group(),new=new));f[k]=f[k][:m.start()]+new+f[k][m.end():]
def pop(k,key,title,body):
 m=re.search(r'<template data-pop="'+re.escape(key)+r'"[^>]*>.*?</template>',f[k],re.S);assert m,key
 new=f'<template data-pop="{key}" data-title="{title}">{body}</template>';log.append(dict(kind='popup',file=k,old=m.group(),new=new));f[k]=f[k][:m.start()]+new+f[k][m.end():]
para('a','L’excès de globuline','<p>La quantité de TBG et son affinité peuvent varier indépendamment. Un déficit héréditaire lié à SERPINA7 abaisse les hormones totales ; une duplication ou triplication peut produire un excès et une hyperthyroxinémie totale avec euthyroïdie. Les œstrogènes et la grossesse augmentent aussi la liaison. La maladie grave et l’hypoprotéinémie de la cirrhose peuvent la diminuer ; certains médicaments déplacent T4 de ses protéines. Ces effets ne dispensent pas de vérifier FT4, TSH et méthode, car une dysfonction authentique peut coexister <button class="w" data-k="e07-facteurs-liaison">facteurs de liaison</button> [S17, S19, S41].</p>')
